#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>

// Legacy monolith - credential cache manager
// Handles AWS credential refresh and request processing

typedef struct {
    char *access_key;
    char *secret_key;
    char *session_token;
    int ref_count;
    pthread_mutex_t lock;
    int is_valid;
} credential_cache_t;

static credential_cache_t *g_current_creds = NULL;
static pthread_mutex_t g_swap_lock = PTHREAD_MUTEX_INITIALIZER;

credential_cache_t *cred_cache_new(const char *ak, const char *sk, const char *token) {
    credential_cache_t *c = (credential_cache_t *)malloc(sizeof(credential_cache_t));
    c->access_key = strdup(ak);
    c->secret_key = strdup(sk);
    c->session_token = strdup(token);
    c->ref_count = 1;
    c->is_valid = 1;
    pthread_mutex_init(&c->lock, NULL);
    return c;
}

void cred_cache_release(credential_cache_t *c) {
    if (!c) return;
    pthread_mutex_lock(&c->lock);
    c->ref_count--;
    int should_free = (c->ref_count <= 0);
    pthread_mutex_unlock(&c->lock);

    if (should_free) {
        // BUG: No check if already freed, no nulling of pointer
        // Race window between ref_count check and free
        free(c->access_key);
        free(c->secret_key);
        free(c->session_token);
        pthread_mutex_destroy(&c->lock);
        free(c);  // First free
    }
}

// Called by rotation thread every 60s
void rotate_credentials(const char *new_ak, const char *new_sk, const char *new_token) {
    pthread_mutex_lock(&g_swap_lock);
    credential_cache_t *old = g_current_creds;
    g_current_creds = cred_cache_new(new_ak, new_sk, new_token);
    pthread_mutex_unlock(&g_swap_lock);

    // Release old credentials - but worker threads may still hold references
    cred_cache_release(old);
}

// Called by worker threads to get current credentials
credential_cache_t *acquire_credentials() {
    pthread_mutex_lock(&g_swap_lock);
    credential_cache_t *c = g_current_creds;
    if (c) {
        pthread_mutex_lock(&c->lock);
        c->ref_count++;
        pthread_mutex_unlock(&c->lock);
    }
    pthread_mutex_unlock(&g_swap_lock);
    return c;
}

// Worker thread processing requests
void *handle_request(void *arg) {
    credential_cache_t *creds = acquire_credentials();
    if (!creds) return NULL;

    // Simulate work with credentials
    usleep(100000); // 100ms of processing

    // Use credentials for AWS API call
    printf("Using key: %s\n", creds->access_key);

    // BUG: Double-release due to logic error in error path
    cred_cache_release(creds);

    // Error handling path - accidentally releases again
    if (creds->is_valid == 0) {  // UAF read, but also triggers double-free
        cred_cache_release(creds);  // DOUBLE FREE
    }

    return NULL;
}

// Rotation daemon thread
void *rotation_daemon(void *arg) {
    char ak[64], sk[128], token[512];
    while (1) {
        // Fetch new credentials from instance metadata / secrets manager
        snprintf(ak, sizeof(ak), "AKIA%040d", rand());
        snprintf(sk, sizeof(sk), "secret_%060d", rand());
        snprintf(token, sizeof(token), "FwoGZX_%0200d", rand());

        rotate_credentials(ak, sk, token);
        sleep(60);  // Rotate every 60 seconds
    }
    return NULL;
}

int main() {
    g_current_creds = cred_cache_new("AKIAIOSFODNN7EXAMPLE",
                                      "wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY",
                                      "FwoGZXIvYXdzEBYaDHqa0AP1");

    pthread_t rotator;
    pthread_create(&rotator, NULL, rotation_daemon, NULL);

    // Accept and process requests
    while (1) {
        pthread_t worker;
        pthread_create(&worker, NULL, handle_request, NULL);
        pthread_detach(worker);
        usleep(10000); // 10ms between requests
    }

    return 0;
}
